"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["40331"],{10205(e){e.exports=JSON.parse('{"id":"FIN-798","slug":"aggregate-supply","term":"Aggregate Supply","also_known_as":[],"difficulty":"Intermediate","definition":"Aggregate supply is the total amount of goods and services that all businesses in an economy are willing and able to produce at a given overall price level, over a period of time.","explanation":["Aggregate supply reflects the economy\'s productive capacity. In the long run, it depends on the quantity and quality of the factors of production: the number of workers and their skills, the stock of capital such as machinery and buildings, natural resources and the technology used to combine them.","In the short run, businesses can increase output somewhat by using existing resources more intensively, for example through overtime. But in the long run, sustained increases in output require growth in productive capacity.","Aggregate supply can be affected by shocks. For example, a sharp rise in oil prices increases production costs across the economy, reducing aggregate supply. This tends to push prices up and output down at the same time, a combination that can lead to stagflation.","Policies aimed at increasing aggregate supply over time are often called supply-side policies. They include investing in education and training, improving infrastructure, encouraging innovation and reducing barriers to business activity."],"note":"","total":1500,"prev":{"slug":"aggregate-demand","term":"Aggregate Demand"},"next":{"slug":"algorithmic-trading","term":"Algorithmic Trading"}}')}}]);